    39→    IBeaconBlockRootHandler beaconBlockRootHandler,
    40→    IBlockhashStore blockHashStore,
    41→    ILogManager logManager,
    42→    IWithdrawalProcessor withdrawalProcessor,
    43→    IExecutionRequestsProcessor executionRequestsProcessor)
    44→    : IBlockProcessor
    45→{
    46→    private readonly ILogger _logger = logManager.GetClassLogger();
    47→    protected readonly WorldStateMetricsDecorator _stateProvider = new WorldStateMetricsDecorator(stateProvider);
    48→    private readonly IReceiptsRootCalculator _receiptsRootCalculator = ReceiptsRootCalculator.Instance;
    49→
    50→    /// <summary>
    51→    /// We use a single receipt tracer for all blocks. Internally receipt tracer forwards most of the calls
    52→    /// to any block-specific tracers.
    53→    /// </summary>
    54→    protected BlockReceiptsTracer ReceiptsTracer { get; set; } = new();
    55→
    56→    public (Block Block, TxReceipt[] Receipts) ProcessOne(Block suggestedBlock, ProcessingOptions options, IBlockTracer blockTracer, IReleaseSpec spec, CancellationToken token)
    57→    {
    58→        if (_logger.IsTrace) _logger.Trace($"Processing block {suggestedBlock.ToString(Block.Format.Short)} ({options})");
    59→
    60→        ApplyDaoTransition(suggestedBlock);
    61→        Block block = PrepareBlockForProcessing(suggestedBlock);
    62→        TxReceipt[] receipts = ProcessBlock(block, blockTracer, options, spec, token);
    63→        ValidateProcessedBlock(suggestedBlock, options, block, receipts);
    64→        if (options.ContainsFlag(ProcessingOptions.StoreReceipts))
    65→        {
    66→            StoreTxReceipts(block, receipts, spec);
    67→        }
    68→
    69→        return (block, receipts);
    70→    }
